configuration:
hbase.tmp.dir /mnt/hbase
hbase.rootdir hdfs://zookage/apps/hbase
hbase.cluster.distributed true
hbase.use.dynamic.jars false
hbase.zookeeper.quorum zookeeper-server-0.zookeeper-server.zookage.svc.cluster.local,zookeeper-server-1.zookeeper-server.zookage.svc.cluster.local,zookeeper-server-2.zookeeper-server.zookage.svc.cluster.local
hbase.security.authorization true
hbase.security.authentication {{ or (index .Values "hbase_security_authentication") "simple" | html }}
hbase.security.authentication.ui {{ or (index .Values "hbase_security_authentication_ui") "simple" | html }}
hbase.security.authentication.spnego.kerberos.principal HTTP/_HOST@ZOOKAGE.LOCAL
hbase.security.authentication.spnego.kerberos.keytab /etc/secrets/hbase/hbase.keytab
hbase.master.kerberos.principal hbase/_HOST@ZOOKAGE.LOCAL
hbase.master.keytab.file /etc/secrets/hbase/hbase.keytab
hbase.regionserver.kerberos.principal hbase/_HOST@ZOOKAGE.LOCAL
hbase.regionserver.keytab.file /etc/secrets/hbase/hbase.keytab
{{- if index .Values "hbase_zookeeper_client_keytab_file" }}
hbase.zookeeper.client.keytab.file {{ index .Values "hbase_zookeeper_client_keytab_file" | html }}
hbase.zookeeper.client.kerberos.principal {{ index .Values "hbase_zookeeper_client_kerberos_principal" | html }}
hbase.zookeeper.property.client.secure true
hbase.zookeeper.property.clientCnxnSocket org.apache.zookeeper.ClientCnxnSocketNetty
hbase.zookeeper.property.ssl.keyStore.location /etc/secrets/zookeeper-client/zookeeper-client.jks
hbase.zookeeper.property.ssl.keyStore.password zookage
hbase.zookeeper.property.ssl.trustStore.location /etc/hadoop/conf/zookage-truststore.jks
hbase.zookeeper.property.ssl.trustStore.password zookage
{{- end }}
hbase.coprocessor.master.classes {{ or (index .Values "hbase_coprocessor_classes") "" | html }}
hbase.coprocessor.region.classes {{ or (index .Values "hbase_coprocessor_classes") "" | html }}
